-- SOURCE tables.sql sha256=6194c9c24f8a87215cf0f5c032b863a3d77f78c46f61566ae45bdc001afa1ba3
-- New forward schema after Stage 1; no retired academic tables are restored.
CREATE TABLE public.study_semesters (
    study_semester_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    program_id uuid NOT NULL,
    academic_year_id uuid NOT NULL,
    study_semester_number integer NOT NULL CHECK (study_semester_number BETWEEN 1 AND 30),
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    description text CHECK (length(description) <= 2000),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (program_id, institution_id)
        REFERENCES public.programs (program_id, institution_id) ON DELETE RESTRICT,
    FOREIGN KEY (academic_year_id, institution_id)
        REFERENCES public.academic_years (academic_year_id, institution_id) ON DELETE RESTRICT,
    UNIQUE (study_semester_id, institution_id),
    UNIQUE (institution_id, program_id, academic_year_id, study_semester_number)
);
CREATE UNIQUE INDEX academic_structure_semester_code
    ON public.study_semesters (institution_id, program_id, academic_year_id, lower(btrim(code)));
CREATE INDEX academic_structure_semester_year
    ON public.study_semesters (institution_id, academic_year_id);

CREATE TABLE public.subjects (
    subject_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    department_id uuid NOT NULL,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    description text CHECK (length(description) <= 2000),
    credits numeric NOT NULL CHECK (credits > 0 AND credits <= 100
        AND credits::text NOT IN ('NaN', 'Infinity', '-Infinity')),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (department_id, institution_id)
        REFERENCES public.departments (department_id, institution_id) ON DELETE RESTRICT,
    UNIQUE (subject_id, institution_id)
);
CREATE UNIQUE INDEX academic_structure_subject_code
    ON public.subjects (institution_id, department_id, lower(btrim(code)));

COMMENT ON TABLE public.study_semesters IS
    'Degree study progress in one program and academic year; not a dated calendar term.';
COMMENT ON COLUMN public.study_semesters.study_semester_number IS
    'Study sequence, e.g. 5 for Fifth Semester; independent of calendar-term numbering.';
COMMENT ON TABLE public.subjects IS
    'Reusable department-owned subjects, such as Data Mining; distinct from degree programs.';

-- SOURCE permissions.sql sha256=994533fa2b7117d9616b93b623513d3519ebb86b850842b73cd9f5afbdb2c3f5
-- Only the four exact Stage 2 permissions; no staff delegation or wildcards.
INSERT INTO public.permissions (code, name, description, scope, is_active)
SELECT resource || '.' || operation, title || ' ' || operation,
       'Academic Setup: ' || title || ' ' || operation, 'institution', true
FROM (VALUES ('semesters', 'Study semesters'), ('subjects', 'Reusable subjects')) AS resources(resource, title)
CROSS JOIN (VALUES ('read'), ('manage')) AS operations(operation)
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    scope = EXCLUDED.scope, is_active = true, updated_at = now();

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.permission_id
FROM public.roles r CROSS JOIN public.permissions p
WHERE r.name = 'admin' AND p.code IN (
    'semesters.read', 'semesters.manage', 'subjects.read', 'subjects.manage'
)
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- SOURCE validation.sql sha256=d4f7f7256efeb42a47e677b0eb9b6c44b5673a103d798e84e5232462f26029d1
-- Shared Stage 1 tenant lock serializes parent changes and both generations of writes.
CREATE FUNCTION public.validate_academic_structure() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    item jsonb := to_jsonb(NEW);
    previous jsonb;
    key text;
    parent_active boolean;
    check_parent boolean := TG_OP = 'INSERT';
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || NEW.institution_id::text, 0)
    );
    IF TG_OP = 'UPDATE' THEN
        previous := to_jsonb(OLD);
        FOR key IN SELECT jsonb_object_keys(item) LOOP
            IF (key LIKE '%\_id' ESCAPE '\' OR key IN ('created_at', 'study_semester_number'))
               AND item -> key IS DISTINCT FROM previous -> key THEN
                RAISE EXCEPTION 'Academic identity and ancestry are immutable' USING ERRCODE = '22023';
            END IF;
        END LOOP;
        check_parent := NEW.is_active AND NOT OLD.is_active;
    END IF;
    IF check_parent THEN
        PERFORM 1 FROM public.institutions i
        JOIN public.organizations o ON o.organization_id = i.organization_id
        WHERE i.institution_id = NEW.institution_id
          AND i.is_active AND i.status = 'active' AND o.status = 'active'
        FOR SHARE OF i, o;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Active institution and organization required' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF TG_TABLE_NAME = 'study_semesters' THEN
        SELECT p.is_active AND d.is_active AND y.is_active INTO parent_active
        FROM public.programs p
        JOIN public.departments d
          ON d.department_id = p.department_id AND d.institution_id = p.institution_id
        JOIN public.academic_years y ON y.academic_year_id = NEW.academic_year_id
          AND y.institution_id = NEW.institution_id
        WHERE p.program_id = NEW.program_id AND p.institution_id = NEW.institution_id
        FOR SHARE OF p, d, y;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Program or academic year not found in institution' USING ERRCODE = '23503';
        END IF;
    ELSE
        SELECT d.is_active INTO parent_active FROM public.departments d
        WHERE d.department_id = NEW.department_id AND d.institution_id = NEW.institution_id
        FOR SHARE OF d;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Department not found in institution' USING ERRCODE = '23503';
        END IF;
    END IF;
    IF check_parent AND NOT parent_active THEN
        RAISE EXCEPTION 'Active academic parents required' USING ERRCODE = '23514';
    END IF;
    NEW.name := btrim(NEW.name);
    NEW.code := btrim(NEW.code);
    IF TG_OP = 'INSERT' THEN NEW.created_at := now(); END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- SOURCE parent_guards.sql sha256=5ce05cf3488b1c3cf7199d8506a96a1fe35e32075d360bd2e01683e842b86098
-- Extend deactivation protection without changing Stage 1 routines or sources.
CREATE FUNCTION public.guard_academic_structure_parent() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || NEW.institution_id::text, 0)
    );
    IF NEW.is_active THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME = 'departments' THEN
        IF EXISTS (
            SELECT 1 FROM public.subjects s
            WHERE s.department_id = NEW.department_id
              AND s.institution_id = NEW.institution_id AND s.is_active
        ) THEN
            RAISE EXCEPTION 'Deactivate dependent subjects first' USING ERRCODE = '23514';
        END IF;
        -- Existing Stage 1 guard already refuses active degree programs.
    ELSIF TG_TABLE_NAME = 'programs' THEN
        IF EXISTS (
            SELECT 1 FROM public.study_semesters s
            WHERE s.program_id = NEW.program_id
              AND s.institution_id = NEW.institution_id AND s.is_active
        ) THEN
            RAISE EXCEPTION 'Deactivate dependent study semesters first' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'academic_years' THEN
        IF EXISTS (
            SELECT 1 FROM public.study_semesters s
            WHERE s.academic_year_id = NEW.academic_year_id
              AND s.institution_id = NEW.institution_id AND s.is_active
        ) THEN
            RAISE EXCEPTION 'Deactivate dependent study semesters first' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DO $$
DECLARE entity text;
BEGIN
    FOREACH entity IN ARRAY ARRAY['departments', 'programs', 'academic_years'] LOOP
        EXECUTE format('CREATE TRIGGER academic_structure_parent_guard BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_academic_structure_parent()', entity);
    END LOOP;
END;
$$;

-- SOURCE write.sql sha256=ca829c6c21e19fc76b56dad7cdd3fdf4252940c9ff0147cb45d540d700c8318b
CREATE FUNCTION public.manage_academic_structure(
    p_actor_user_id uuid, p_institution_id uuid, p_entity text, p_record_id uuid, p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    relation_name text;
    id_column text;
    allowed text[];
    immutable text[];
    required text[] := ARRAY['name', 'code'];
    key text;
    kind text;
    before_row jsonb;
    after_row jsonb;
    effective jsonb;
    item_id uuid := COALESCE(p_record_id, gen_random_uuid());
    fields text;
    expressions text;
BEGIN
    CASE p_entity
    WHEN 'semesters' THEN
        relation_name := 'study_semesters';
        id_column := 'study_semester_id';
        immutable := ARRAY['program_id', 'academic_year_id', 'study_semester_number'];
        allowed := ARRAY['name', 'code', 'description', 'is_active'] || immutable;
        required := required || immutable;
    WHEN 'subjects' THEN
        relation_name := 'subjects';
        id_column := 'subject_id';
        immutable := ARRAY['department_id'];
        allowed := ARRAY['name', 'code', 'description', 'credits', 'is_active'] || immutable;
        required := required || ARRAY['department_id', 'credits'];
    ELSE RAISE EXCEPTION 'Unknown academic structure entity' USING ERRCODE = '22023';
    END CASE;
    -- Reuse exact scoped active-admin authority; do not replace its Stage 1 helper.
    PERFORM public.assert_academic_foundation_actor(p_actor_user_id, p_institution_id, p_entity);
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' OR p_payload = '{}'::jsonb THEN
        RAISE EXCEPTION 'Academic fields required' USING ERRCODE = '22023';
    END IF;
    IF p_record_id IS NULL AND NOT p_payload ?& required THEN
        RAISE EXCEPTION 'Required academic fields missing' USING ERRCODE = '22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(p_payload) LOOP
        IF NOT key = ANY(allowed) OR (p_record_id IS NOT NULL AND key = ANY(immutable)) THEN
            RAISE EXCEPTION 'Unsupported or immutable academic field' USING ERRCODE = '22023';
        END IF;
        kind := jsonb_typeof(p_payload -> key);
        IF kind = 'null' AND key <> 'description' THEN
            RAISE EXCEPTION 'Required academic field cannot be null' USING ERRCODE = '22023';
        END IF;
        IF kind <> 'null' AND (
            (key = 'is_active' AND kind <> 'boolean') OR
            (key IN ('credits', 'study_semester_number') AND kind <> 'number') OR
            (key NOT IN ('is_active', 'credits', 'study_semester_number') AND kind <> 'string')
        ) THEN
            RAISE EXCEPTION 'Invalid academic field type' USING ERRCODE = '22023';
        END IF;
        IF key = 'study_semester_number' AND NOT (p_payload ->> key) ~ '^[0-9]+$' THEN
            RAISE EXCEPTION 'Study semester number must be an integer' USING ERRCODE = '22023';
        END IF;
    END LOOP;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || p_institution_id::text, 0)
    );
    IF p_record_id IS NOT NULL THEN
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I = $1 AND institution_id = $2 FOR UPDATE',
                       relation_name, id_column) INTO before_row USING p_record_id, p_institution_id;
        IF before_row IS NULL THEN
            RAISE EXCEPTION 'Academic record not found' USING ERRCODE = 'P0002';
        END IF;
    END IF;
    effective := COALESCE(before_row, '{}'::jsonb) || p_payload ||
        jsonb_build_object(id_column, item_id, 'institution_id', p_institution_id);
    -- SQL identifiers come only from the closed entity/field whitelists.
    -- Omitted create fields keep their database defaults; all values are bound.
    SELECT string_agg(format('%I', k), ','), string_agg(format('r.%I', k), ',')
    INTO fields, expressions
    FROM jsonb_object_keys(CASE WHEN p_record_id IS NULL THEN effective ELSE p_payload END) AS k;
    IF p_record_id IS NULL THEN
        EXECUTE format('INSERT INTO public.%I AS t (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r RETURNING to_jsonb(t)',
                       relation_name, fields, expressions, relation_name) INTO after_row USING effective;
    ELSE
        EXECUTE format('UPDATE public.%I AS t SET (%s) = (SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r) WHERE %I = $2 AND institution_id = $3 RETURNING to_jsonb(t)',
                       relation_name, fields, expressions, relation_name, id_column)
        INTO after_row USING effective, p_record_id, p_institution_id;
    END IF;
    INSERT INTO public.admin_audit_log (
        actor_user_id, institution_id, action, table_name, record_id, record_data, status
    ) VALUES (
        p_actor_user_id, p_institution_id,
        'academic.' || p_entity || CASE WHEN p_record_id IS NULL THEN '.create'
            WHEN before_row ->> 'is_active' = 'true' AND after_row ->> 'is_active' = 'false'
                THEN '.deactivate'
            WHEN before_row ->> 'is_active' = 'false' AND after_row ->> 'is_active' = 'true'
                THEN '.activate' ELSE '.update' END,
        relation_name, item_id::text, jsonb_build_object('before', before_row, 'after', after_row), 'success'
    );
    RETURN after_row;
END;
$$;

-- SOURCE security.sql sha256=0fb13814a40f40b39ec1fc1dee954583c50fb51fe41349dc42c65bbb53a73987
DO $$
DECLARE relation_name text;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY['study_semesters', 'subjects'] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres', relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', relation_name);
        -- Browser roles have no policies; trusted reads remain tenant-filtered.
        -- The service role cannot mutate tables directly or delete records.
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role', relation_name);
        EXECUTE format('CREATE TRIGGER academic_structure_validate BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_academic_structure()', relation_name);
    END LOOP;
END;
$$;
ALTER FUNCTION public.validate_academic_structure() OWNER TO postgres;
ALTER FUNCTION public.guard_academic_structure_parent() OWNER TO postgres;
ALTER FUNCTION public.manage_academic_structure(uuid, uuid, text, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.validate_academic_structure(),
    public.guard_academic_structure_parent(),
    public.manage_academic_structure(uuid, uuid, text, uuid, jsonb)
    FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.manage_academic_structure(uuid, uuid, text, uuid, jsonb) TO service_role;
NOTIFY pgrst, 'reload schema';
COMMIT;
